def paginate(scope)
  @current_page = current_page
  @per_page = per_page

  records = scope.offset((@current_page - 1) * @per_page).limit(@per_page + 1).to_a
  @next_page = @current_page + 1 if records.size > @per_page

  records.first(@per_page)
end

